sealed class ErrorCode: Exception() {
    // Each variant is a nested class
    
    class Input(
        val `msg`: String
        ) : ErrorCode() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class IoException(
        val `msg`: String
        ) : ErrorCode() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class InvalidState(
        val `msg`: String
        ) : ErrorCode() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Unexpected(
        val `msg`: String
        ) : ErrorCode() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class CredentialRevoked(
        val `msg`: String
        ) : ErrorCode() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class InvalidUserRevocId(
        val `msg`: String
        ) : ErrorCode() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class ProofRejected(
        val `msg`: String
        ) : ErrorCode() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class RevocationRegistryFull(
        val `msg`: String
        ) : ErrorCode() {
        override val message
            get() = "msg=${ `msg` }"
    }
    

    companion object ErrorHandler : CallStatusErrorHandler<ErrorCode> {
        override fun lift(error_buf: RustBuffer.ByValue): ErrorCode = FfiConverterTypeErrorCode.lift(error_buf)
    }

    
}

public object FfiConverterTypeErrorCode : FfiConverterRustBuffer<ErrorCode> {
    override fun read(buf: ByteBuffer): ErrorCode {
        

        return when(buf.getInt()) {
            1 -> ErrorCode.Input(
                FfiConverterString.read(buf),
            )
            2 -> ErrorCode.IoException(
                FfiConverterString.read(buf),
            )
            3 -> ErrorCode.InvalidState(
                FfiConverterString.read(buf),
            )
            4 -> ErrorCode.Unexpected(
                FfiConverterString.read(buf),
            )
            5 -> ErrorCode.CredentialRevoked(
                FfiConverterString.read(buf),
            )
            6 -> ErrorCode.InvalidUserRevocId(
                FfiConverterString.read(buf),
            )
            7 -> ErrorCode.ProofRejected(
                FfiConverterString.read(buf),
            )
            8 -> ErrorCode.RevocationRegistryFull(
                FfiConverterString.read(buf),
            )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: ErrorCode): Int {
        return when(value) {
            is ErrorCode.Input -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is ErrorCode.IoException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is ErrorCode.InvalidState -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is ErrorCode.Unexpected -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is ErrorCode.CredentialRevoked -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4
